SELECT new_id, id, work_id, client_id, channel_id, content_type, title, content, user_name, `data`, done, data_status, publish_time, create_time, ext_fields, biz_ext_attrs, biz_ext_attrs2, biz_ext_attrs3 FROM ays_meta_data_analysis where client_id = #{clientId}
and work_id in
#{item}
and data_status in
#{item}
and date(publish_time) BETWEEN DATE(#{startTime}) and DATE(#{endTime})
and channel_id in
#{item}
and ext_fields -> '$.showType' = #{showType}
and ( trim(biz_ext_attrs -> '$.category_1') like concat('%',#{keywords},'%') or trim(biz_ext_attrs -> '$.category_2') like concat('%',#{keywords},'%') or trim(biz_ext_attrs -> '$.category_3') like concat('%',#{keywords},'%') or trim(biz_ext_attrs -> '$.category_4') like concat('%',#{keywords},'%') or trim(biz_ext_attrs -> '$.category_5') like concat('%',#{keywords},'%') or trim(biz_ext_attrs -> '$.abstract') like concat('%',#{keywords},'%') or content like concat('%',#{keywords},'%') )
order by new_id desc limit #{pageNum},#{pageSize}

