select ANY_VALUE(new_id) as new_id, ARRAY_AGG(car_series_name) as carSeriesName, ANY_VALUE(biz_ext_attrs) as bizExtAttrs, ANY_VALUE(publish_time) as publishTime, ARRAY_AGG(mention_car_series) as mentionCarSeries from ins_ays_post_process_data where client_id = #{clientId} and showType ="2"
and date(publish_time) BETWEEN DATE(#{startTime}) and DATE(#{endTime})
and channel_id in
#{item}
and label_type in
#{item}
and label_type_level_four_code not in
#{item}
and small_area_code in
#{item}
and car_series_name in
#{item}
and car_series_name in
#{item}
and brand_code_name in
#{item}
and mention_car_series IS not null and mention_car_series!="[]" and array_length(array_intersect(split(mention_car_series ,',') ,split(#{mentionCarSeriesString} ,','))) > 0
and (category_1 like concat('%',#{keywords},'%') or category_2 like concat('%',#{keywords},'%') or category_3 like concat('%',#{keywords},'%') or category_4 like concat('%',#{keywords},'%') or category_5 like concat('%',#{keywords},'%') or abstract like concat('%',#{keywords},'%') or original_text_scene like concat('%',#{keywords},'%') )
group by original_id order by publishTime desc,original_id desc limit #{pageNum},#{pageSize}

